playZero(160);
resetOscPhase();
repeat (32768) {
  c_freq_osc_0 = 0;
  playZero(176);
  setSweepStep(freq_osc_0,c_freq_osc_0++);
  playZero(6000);
  startQA(0,1,0,0,2);
  setTrigger(0);
  repeat (100) {
    playZero(176);
    setSweepStep(freq_osc_0,c_freq_osc_0++);
    playZero(6000);
    startQA(0,1,0,0,2);
    setTrigger(0);
  }
}

waitDigTrigger(1);
playZero(160);
resetOscPhase();
executeTableEntry(0);
repeat (32768) {
  repeat (101) {
    playZero(6176);
  }
}
